///
/// @brief Main sorting implementation with reversed priority order
/// @note Process from highest priority (1) to lower priority (up to 1), then default (0)
/// @warning Passing more than 32 clauses will cause a compile error:
///          - Error message: 'SORT_CLAUSES_IMPL_*' was not declared in this scope
///          - To fix: cd solomon/util && julia jl/sort_clause.jl --max N
///                   (where N >= your clause count + 1)
/// @note To increase priority levels, regenerate with:
///          - cd solomon/util && julia jl/sort_clause.jl --level M
///                   (where M >= your required priority levels)
///
#define SORT_CLAUSES_IMPL(...) UTIL_CLOAK_CAT(SORT_CLAUSES_IMPL_, NUM_ARGS(__VA_ARGS__))(__VA_ARGS__)

